scenario.en:
// The guard claims Order but only checks id
type Order = { id: string; total: number };
function isOrder(x: unknown): x is Order {
  return typeof x === "object" && x !== null && "id" in x;
}
const v: unknown = { id: "o1" };
if (isOrder(v)) v.total.toFixed(2);

